SourceCode.Declaration:
internal class GUPPriceEnginePrematchObject
{
    private SalesTable salesTable;
    private SalesLine salesLine;

    // Key = datasource Id (table id or provider class id), value = GUPPriceEngineRelatedDataObject.
    private Map salesTableRelatedDataMap;
    private Map salesLineRelatedDataMap;

    // List of GUPPriceEngineLineAggregationObject, sorted from highest priority to lowest.
    private List journalLineList;

    // List of applied GUPPriceEngineMarginComponent, sorted by computing sequence.
    private List marginComponentList;

}

Method.Source:
public void new (SalesTable _salesTable, SalesLine _salesLine)
{
    this.salesTable = _salesTable;
    this.salesLine = _salesLine;
}

public Map parmSalesTableRelatedDataMap (Map _salesTableRelatedDataMap = null) 
{
    if (_salesTableRelatedDataMap != null)
    {
        this.salesTableRelatedDataMap = _salesTableRelatedDataMap;
    }
    return this.salesTableRelatedDataMap;
}

public Map parmSalesLineRelatedDataMap (Map _salesLineRelatedDataMap = null)
{
    if (_salesLineRelatedDataMap != null)
    {
        this.salesLineRelatedDataMap = _salesLineRelatedDataMap;
    }
    return this.salesLineRelatedDataMap;
}

public List parmMarginComponentList (List _marginComponentList = null)
{
    if (_marginComponentList != null)
    {
        this.marginComponentList = _marginComponentList;
    }
    return this.marginComponentList;
}

public List parmTradeAgreementJournalLineList (List _journalLineList = null)
{
    if (_journalLineList != null)
    {
        this.journalLineList = _journalLineList;
    }
    return this.journalLineList;
}

public GUPPriceEngineRelatedDataObject findTradeAgreementRelatedDataObject (str _datasourceId)
{
    // Assume salesTable & salesLine always have NO datasource collision.
    if (this.salesTableRelatedDataMap.exists(_datasourceId))
    {
        return this.salesTableRelatedDataMap.lookup(_datasourceId);
    }
    else
    {
        return this.salesLineRelatedDataMap.lookup(_datasourceId);
    }
}
